 * Exo heat-3d driver: mirrors PolyBench/C heat-3d.c but calls the Exo-generated kernel.
 *
 * Original header:
 *   Louis-Noel Pouchet <pouchet.ohio-state.edu>
 *   Tomofumi Yuki <tomofumi.yuki.fr>
 *
 * Web address: http://polybench.sourceforge.net
 */
/* heat-3d.c: this file is part of PolyBench/C */

#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "heat-3d.h"

/* Include the Exo-generated kernel header. */
#include "generated/heat-3d/heat-3d.h"


/* Array initialization. */
static
void init_array (int n,
		 DATA_TYPE POLYBENCH_3D(A,N,N,N,n,n,n),
		 DATA_TYPE POLYBENCH_3D(B,N,N,N,n,n,n))
{
  int i, j, k;

  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++)
      for (k = 0; k < n; k++)
        A[i][j][k] = B[i][j][k] = (DATA_TYPE) (i + j + (n-k))* 10 / (n);
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_3D(A,N,N,N,n,n,n))

{
  int i, j, k;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("A");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++)
      for (k = 0; k < n; k++) {
         if ((i * n * n + j * n + k) % 20 == 0) fprintf(POLYBENCH_DUMP_TARGET, "\n");
         fprintf(POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, A[i][j][k]);
      }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}

/* Kernel implementation in Exo:
EXO START
from __future__ import annotations

from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM

@proc
def kernel_heat_3d(
    tsteps: size,
    n: size,
    A: DATA_TYPE[n, n, n] @ DRAM,
    B: DATA_TYPE[n, n, n] @ DRAM,
):
    # We update only interior points [1 .. n-2] in each spatial dimension.
    assert n > 2

    for t in seq(0, tsteps):
        # ------------------------------------------------------------------
        # First half-step: update B from A
        # ------------------------------------------------------------------
        for i in seq(1, n - 1):
            for j in seq(1, n - 1):
                for k in seq(1, n - 1):
                    # Load the 7-point stencil neighborhood of A into scalars.
                    # This reduces repeated memory accesses and lets the
                    # compiler keep values in registers.
                    center: DATA_TYPE
                    xm: DATA_TYPE
                    xp: DATA_TYPE
                    ym: DATA_TYPE
                    yp: DATA_TYPE
                    zm: DATA_TYPE
                    zp: DATA_TYPE

                    center = A[i, j, k]
                    xp = A[i + 1, j, k]
                    xm = A[i - 1, j, k]
                    yp = A[i, j + 1, k]
                    ym = A[i, j - 1, k]
                    zp = A[i, j, k + 1]
                    zm = A[i, j, k - 1]

                    B[i, j, k] = (
                        0.125 * (xp - 2.0 * center + xm)
                      + 0.125 * (yp - 2.0 * center + ym)
                      + 0.125 * (zp - 2.0 * center + zm)
                      + center
                    )

        # ------------------------------------------------------------------
        # Second half-step: update A from B
        # ------------------------------------------------------------------
        for i in seq(1, n - 1):
            for j in seq(1, n - 1):
                for k in seq(1, n - 1):
                    # Same stencil, now centered on B.
                    center: DATA_TYPE
                    xm: DATA_TYPE
                    xp: DATA_TYPE
                    ym: DATA_TYPE
                    yp: DATA_TYPE
                    zm: DATA_TYPE
                    zp: DATA_TYPE

                    center = B[i, j, k]
                    xp = B[i + 1, j, k]
                    xm = B[i - 1, j, k]
                    yp = B[i, j + 1, k]
                    ym = B[i, j - 1, k]
                    zp = B[i, j, k + 1]
                    zm = B[i, j, k - 1]

                    A[i, j, k] = (
                        0.125 * (xp - 2.0 * center + xm)
                      + 0.125 * (yp - 2.0 * center + ym)
                      + 0.125 * (zp - 2.0 * center + zm)
                      + center
                    )

# ----------------------------------------------------------------------
# Scheduling:
#   - Parallelize the outer spatial loops over i for both updates.
#     Each (i,j,k) writes to a distinct cell, so there are no loop-carried
#     dependencies across i in a single time-step.
#   - Tile and unroll the innermost k-loops with factor 4 to improve
#     instruction-level parallelism and aid vectorization while handling
#     non-multiple sizes safely via guarded tails.
#   - Finally, simplify the resulting code.
# ----------------------------------------------------------------------

# Parallelize the i-loops of the B-update and A-update.
kernel_heat_3d = parallelize_loop(kernel_heat_3d,
                                  kernel_heat_3d.find_loop("i #0"))
kernel_heat_3d = parallelize_loop(kernel_heat_3d,
                                  kernel_heat_3d.find_loop("i #1"))

# For the first k-loop (in the B-update), tile by 4 and unroll the inner tile.
kernel_heat_3d = divide_loop(
    kernel_heat_3d,
    kernel_heat_3d.find_loop("k #0"),
    4,
    ("k_outer0", "k_inner0"),
    tail="guard",
)
kernel_heat_3d = unroll_loop(kernel_heat_3d,
                             kernel_heat_3d.find_loop("k_inner0"))

# For the second k-loop (in the A-update), apply the same transformation.
kernel_heat_3d = divide_loop(
    kernel_heat_3d,
    kernel_heat_3d.find_loop("k #1"),
    4,
    ("k_outer1", "k_inner1"),
    tail="guard",
)
kernel_heat_3d = unroll_loop(kernel_heat_3d,
                             kernel_heat_3d.find_loop("k_inner1"))

# Perform algebraic simplifications after scheduling.
kernel_heat_3d = simplify(kernel_heat_3d)

EXO END
*/


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int tsteps = TSTEPS;

  /* Variable declaration/allocation. */
  POLYBENCH_3D_ARRAY_DECL(A, DATA_TYPE, N, N, N, n, n, n);
  POLYBENCH_3D_ARRAY_DECL(B, DATA_TYPE, N, N, N, n, n, n);

  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(B));

  /* Start timer. */
  polybench_start_instruments;

  /* Run Exo kernel. Flatten 3D views to 1D pointers. */
  kernel_heat_3d(/*ctxt=*/NULL, tsteps, n,
                 (DATA_TYPE*)POLYBENCH_ARRAY(A),
                 (DATA_TYPE*)POLYBENCH_ARRAY(B));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(A)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);

  return 0;
}
