/* Kernel implementation in Exo:
EXO START
from __future__ import annotations

from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM


# Base heat-3d stencil: straightforward 7-point 3D update,
# matching the original PolyBench kernel.
@proc
def kernel_heat_3d_unoptimized(
    tsteps: size,
    n: size,
    A: DATA_TYPE[n, n, n] @ DRAM,
    B: DATA_TYPE[n, n, n] @ DRAM,
):
    # We update only interior points [1:n-1) in each dimension.
    assert n > 2

    for t in seq(0, tsteps):
        # Update B from A
        for i in seq(1, n - 1):
            for j in seq(1, n - 1):
                for k in seq(1, n - 1):
                    B[i, j, k] = (
                        0.125 * (A[i + 1, j,     k    ] - 2.0 * A[i, j, k] + A[i - 1, j,     k    ])
                      + 0.125 * (A[i,     j + 1, k    ] - 2.0 * A[i, j, k] + A[i,     j - 1, k    ])
                      + 0.125 * (A[i,     j,     k + 1] - 2.0 * A[i, j, k] + A[i,     j,     k - 1])
                      + A[i, j, k]
                    )

        # Update A from B
        for i in seq(1, n - 1):
            for j in seq(1, n - 1):
                for k in seq(1, n - 1):
                    A[i, j, k] = (
                        0.125 * (B[i + 1, j,     k    ] - 2.0 * B[i, j, k] + B[i - 1, j,     k    ])
                      + 0.125 * (B[i,     j + 1, k    ] - 2.0 * B[i, j, k] + B[i,     j - 1, k    ])
                      + 0.125 * (B[i,     j,     k + 1] - 2.0 * B[i, j, k] + B[i,     j,     k - 1])
                      + B[i, j, k]
                    )


# ---------------------------------------------------------------------------
# Scheduling for performance
#
# We keep the mathematical computation identical, but transform the loop
# nest to:
#   - tile the i/j (slow) spatial dimensions to improve cache locality
#   - keep k as the innermost loop for unit-stride accesses
#   - parallelize outer tiles in i for both A- and B-updates.
#
# Tile sizes are compile-time constants and can be tuned per hardware.
# ---------------------------------------------------------------------------

kernel_heat_3d = kernel_heat_3d_unoptimized

# Tunable tile sizes for the two slow spatial dimensions.
TI = 32
TJ = 32

# Get cursors to the time loop and the two spatial loop nests (B then A).
t_loop = kernel_heat_3d.find_loop("t")
b_i_loop = t_loop.body()[0]          # first i-loop: updates B from A
a_i_loop = t_loop.body()[1]          # second i-loop: updates A from B

# j-loops nested inside each i-loop
b_j_loop = b_i_loop.body().find_loop("j")
a_j_loop = a_i_loop.body().find_loop("j")

# ---- Tile B-update: i and j dimensions ----
# After these transforms, the B-update loop structure is:
#   for t:
#     for io_B:              (tiled i)
#       for jo_B:            (tiled j)
#         for ii_B, jj_B, k  (intra-tile loops, k innermost)
kernel_heat_3d = divide_loop(kernel_heat_3d, b_i_loop, TI, ("io_B", "ii_B"))
kernel_heat_3d = divide_loop(kernel_heat_3d, b_j_loop, TJ, ("jo_B", "jj_B"))
kernel_heat_3d = reorder_loops(kernel_heat_3d, "ii_B jo_B")  # io_B, jo_B, ii_B, jj_B, k

# ---- Tile A-update: i and j dimensions ----
kernel_heat_3d = divide_loop(kernel_heat_3d, a_i_loop, TI, ("io_A", "ii_A"))
kernel_heat_3d = divide_loop(kernel_heat_3d, a_j_loop, TJ, ("jo_A", "jj_A"))
kernel_heat_3d = reorder_loops(kernel_heat_3d, "ii_A jo_A")

# ---- Parallelize over tiles in the i-dimension for both phases ----
# Each (i,j,k) update within a time step is independent, so it is safe
# to parallelize the outermost i-tiles. The barrier at the end of each
# parallel loop preserves the sequential ordering between the B- and
# A-update phases for each time step.
io_B_loop = kernel_heat_3d.find_loop("io_B")
io_A_loop = kernel_heat_3d.find_loop("io_A")

kernel_heat_3d = parallelize_loop(kernel_heat_3d, io_B_loop)
kernel_heat_3d = parallelize_loop(kernel_heat_3d, io_A_loop)
EXO END
*/


int main(int argc, char** argv)
{
