/* Kernel implementation in Exo:
EXO START
from __future__ import annotations

from exo import *
from exo.libs.memories import DRAM
from exo.API_scheduling import *

# 3D heat diffusion kernel: ping-pong between A and B.
# We keep the straightforward 7-point stencil formulation in object code,
# then apply Exo scheduling primitives to parallelize the spatial loops.

@proc
def kernel_heat_3d(
    tsteps: size,
    n: size,
    A: DATA_TYPE[n, n, n] @ DRAM,
    B: DATA_TYPE[n, n, n] @ DRAM,
):
    # We update only the interior points, so we require at least a 3x3x3 grid.
    assert n > 2

    for t in seq(0, tsteps):
        # --- Phase 1: update B from A ---
        for i in seq(1, n - 1):
            for j in seq(1, n - 1):
                for k in seq(1, n - 1):
                    B[i, j, k] = (
                        0.125 * (A[i + 1, j,     k    ] - 2.0 * A[i, j, k] + A[i - 1, j,     k    ])
                      + 0.125 * (A[i,     j + 1, k    ] - 2.0 * A[i, j, k] + A[i,     j - 1, k    ])
                      + 0.125 * (A[i,     j,     k + 1] - 2.0 * A[i, j, k] + A[i,     j,     k - 1])
                      + A[i, j, k]
                    )

        # --- Phase 2: update A from B ---
        for i in seq(1, n - 1):
            for j in seq(1, n - 1):
                for k in seq(1, n - 1):
                    A[i, j, k] = (
                        0.125 * (B[i + 1, j,     k    ] - 2.0 * B[i, j, k] + B[i - 1, j,     k    ])
                      + 0.125 * (B[i,     j + 1, k    ] - 2.0 * B[i, j, k] + B[i,     j - 1, k    ])
                      + 0.125 * (B[i,     j,     k + 1] - 2.0 * B[i, j, k] + B[i,     j,     k - 1])
                      + B[i, j, k]
                    )

# ---------------------------------------------------------------------------
# Scheduling: exploit spatial parallelism.
#
# For each time step, the updates for different i-planes are independent:
#  - Phase 1 writes B[i, :, :] and only reads A.
#  - Phase 2 writes A[i, :, :] and only reads B.
# So we can safely parallelize the i-loops in both phases. Exo will lower
# these to OpenMP pragmas (ignored if the compiler is not using OpenMP).
# ---------------------------------------------------------------------------

# Parallelize the first i-loop (updating B from A).
kernel_heat_3d = parallelize_loop(kernel_heat_3d, kernel_heat_3d.find_loop("i"))

# Parallelize the second i-loop (updating A from B). We select the second
# i-loop by using the "#1" syntactic shorthand in find_loop.
kernel_heat_3d = parallelize_loop(kernel_heat_3d, kernel_heat_3d.find_loop("i #1"))

# Optionally, simplify the final scheduled kernel (constant folding, etc.).
kernel_heat_3d = simplify(kernel_heat_3d)

EXO END
*/


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int tsteps = TSTEPS;

  /* Variable declaration/allocation. */
  POLYBENCH_3D_ARRAY_DECL(A, DATA_TYPE, N, N, N, n, n, n);
  POLYBENCH_3D_ARRAY_DECL(B, DATA_TYPE, N, N, N, n, n, n);

  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(B));

  /* Start timer. */
  polybench_start_instruments;

  /* Run Exo kernel. Flatten 3D views to 1D pointers. */
  kernel_heat_3d(/*ctxt=*/NULL, tsteps, n,
                 (DATA_TYPE*)POLYBENCH_ARRAY(A),
                 (DATA_TYPE*)POLYBENCH_ARRAY(B));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(A)));

  /* Be clean. */
