from __future__ import annotations

from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM

# Baseline 7-point 3D heat stencil with ping-pong buffering between A and B.
@proc
def kernel_heat_3d(
    tsteps: size,
    n: size,
    A: DATA_TYPE[n, n, n] @ DRAM,
    B: DATA_TYPE[n, n, n] @ DRAM,
):
    # We update interior points only; neighbors at +/-1 must exist.
    assert n > 2

    for t in seq(0, tsteps):
        # Phase 1: update B from A at time step t
        for i in seq(1, n - 1):
            for j in seq(1, n - 1):
                for k in seq(1, n - 1):
                    # 7-point stencil using axis-aligned neighbors of A
                    B[i, j, k] = (
                        0.125 * (A[i + 1, j,     k    ] - 2.0 * A[i, j, k] + A[i - 1, j,     k    ])
